export function connectPresence(socket, onPresence) {
  function listener(...args) {
    return onPresence.apply(this, args);
  }
  socket.on('presence', listener);
  try {
    socket.connect();
  } catch (error) {
    socket.off('presence', listener);
    throw error;
  }
  return () => socket.off('presence', listener);
}

